SET NAMES utf8mb4;
CREATE DATABASE IF NOT EXISTS diploma_study_buddy;
USE diploma_study_buddy;
DROP TABLE IF EXISTS notifications,feedback,doubts,progress,questions,quizzes,videos,notes,chapters,subjects,users,semesters,branches;
CREATE TABLE branches(id VARCHAR(30) PRIMARY KEY,name VARCHAR(100) NOT NULL,short_name VARCHAR(20) NOT NULL,icon VARCHAR(10)) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE semesters(id INT AUTO_INCREMENT PRIMARY KEY,number INT UNIQUE NOT NULL);
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(120) UNIQUE NOT NULL,password VARCHAR(255) NOT NULL,role ENUM('student','admin') DEFAULT 'student',branch_id VARCHAR(30),semester INT DEFAULT 3,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(branch_id) REFERENCES branches(id),FOREIGN KEY(semester) REFERENCES semesters(number));
CREATE TABLE subjects(id INT AUTO_INCREMENT PRIMARY KEY,branch_id VARCHAR(30) NOT NULL,semester INT NOT NULL,code VARCHAR(20) NOT NULL,name VARCHAR(120) NOT NULL,icon VARCHAR(10),color VARCHAR(20),UNIQUE(branch_id,semester,code),FOREIGN KEY(branch_id) REFERENCES branches(id),FOREIGN KEY(semester) REFERENCES semesters(number));
CREATE TABLE chapters(id INT AUTO_INCREMENT PRIMARY KEY,subject_id INT NOT NULL,chapter_no INT NOT NULL,title VARCHAR(150) NOT NULL,UNIQUE(subject_id,chapter_no),FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE CASCADE);
CREATE TABLE notes(id INT AUTO_INCREMENT PRIMARY KEY,subject_id INT,title VARCHAR(150) NOT NULL,file_name VARCHAR(255),file_url VARCHAR(500),uploaded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE SET NULL);
CREATE TABLE videos(id INT AUTO_INCREMENT PRIMARY KEY,subject_id INT,title VARCHAR(150) NOT NULL,video_url VARCHAR(500),FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE SET NULL);
CREATE TABLE quizzes(id INT AUTO_INCREMENT PRIMARY KEY,subject_id INT NOT NULL,title VARCHAR(150) NOT NULL,FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE CASCADE);
CREATE TABLE questions(id INT AUTO_INCREMENT PRIMARY KEY,quiz_id INT NOT NULL,question TEXT NOT NULL,option_a VARCHAR(255),option_b VARCHAR(255),option_c VARCHAR(255),option_d VARCHAR(255),correct_option CHAR(1) NOT NULL,marks INT DEFAULT 1,FOREIGN KEY(quiz_id) REFERENCES quizzes(id) ON DELETE CASCADE);
CREATE TABLE progress(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,subject_id INT NOT NULL,chapter_id INT NOT NULL,completed BOOLEAN DEFAULT FALSE,quiz_score INT,last_accessed TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE(user_id,chapter_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE CASCADE,FOREIGN KEY(chapter_id) REFERENCES chapters(id) ON DELETE CASCADE);
CREATE TABLE doubts(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,subject_id INT,question TEXT NOT NULL,answer TEXT,status VARCHAR(30) DEFAULT 'Pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE SET NULL);
CREATE TABLE feedback(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,rating INT,comment TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE notifications(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT,title VARCHAR(150),message TEXT,is_read BOOLEAN DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
